/**
 * Parity of the TypeScript port against the official PyTorch package.
 *
 * The fixture is generated by `tools/make_parity_fixture.py` (CI does this in the
 * `parity` job). Without it the test is skipped.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { TimestralForecaster, TimestralModel } from "../src/model/timestral";

const dir = join(__dirname, "fixtures", "parity");
const have = existsSync(join(dir, "cases.json"));

interface Case {
  name: string;
  context: (number | null)[];
  horizon: number;
  symmetric_averaging: boolean;
  clip_nonnegative: boolean;
  max_context: number | null;
  quantiles: number[][];
}

describe.skipIf(!have)("parity with the official timestral package", () => {
  const load = () => {
    const config = JSON.parse(readFileSync(join(dir, "config.json"), "utf8"));
    const buf = readFileSync(join(dir, "model.safetensors"));
    const ab = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer;
    return new TimestralForecaster(TimestralModel.fromBuffers(config, ab));
  };
  const cases: Case[] = have ? JSON.parse(readFileSync(join(dir, "cases.json"), "utf8")).cases : [];
  const fc = have ? load() : null;

  for (const c of cases) {
    it(c.name, () => {
      const ctx = c.context.map((v) => (v === null ? NaN : v));
      const out = fc!.forecast(ctx, c.horizon, {
        symmetricAveraging: c.symmetric_averaging,
        clipNonnegative: c.clip_nonnegative,
        maxContext: c.max_context ?? undefined,
      });
      const Q = out.levels.length;
      let maxErr = 0;
      let maxRef = 0;
      for (let t = 0; t < c.horizon; t++) {
        for (let i = 0; i < Q; i++) {
          const ref = c.quantiles[t][i];
          maxErr = Math.max(maxErr, Math.abs(out.quantiles[t * Q + i] - ref));
          maxRef = Math.max(maxRef, Math.abs(ref));
        }
      }
      expect(maxErr / Math.max(1, maxRef)).toBeLessThan(2e-4);
    });
  }
});
